"""Apply UI112 after the exact UI111 runtime; inventory review navigation."""
from __future__ import annotations
import base64,hashlib,json,sys,zlib
from pathlib import Path,PurePosixPath
PARENT_MANIFEST_SHA256='3a2063b04e50a8753580dcc5507f73e3b11d647425cb3b568f66d14b2ebe1793'
TARGET_VARIANT='workspace-ui112-inventory-review-navigation-2026-10-13'
FILES={'UI_PATCH.json': {'before': '7342769277159d3c17f8254dda6a7ea0942b8358960921d9e8a33381e19d73b8', 'after': 'd793b92af07475c62b2b64079320bc77338f73aff905d88e88cc165f056152d0', 'bytes': 3165, 'payload': ''}, 'app/static/document_import.css': {'before': 'fd660c82bd371e6b243936dc1cb97edec08c5f902c623be0d88aa8f49ad2879f', 'after': '33abb1bc944ea1e0ecaa995988fb07cbf6a4619ce817b4fea966dd1509e1e6bc', 'bytes': 33185, 'payload': ''}, 'app/static/document_import.js': {'before': '54cd28eab1f889b77424dbeda433f60e40f08dcb2510fa394d3c7a8583abd42e', 'after': 'c46c3e3af15851d4e87f6a6d4bedc76c360a22923aa30d9c5be9f897b7628ed0', 'bytes': 132927, 'payload': ''}, 'app/static/help_catalogue.json': {'before': 'f1380d40c8c242c7f3df9e12c40539df45107b904539a64c70fb97a42e7aa9aa', 'after': 'b15a272ffb6f8628d603e12d85448dda63ed96a2e55745d13d3ef4f0fffce9c5', 'bytes': 459519, 'payload': ''}, 'app/static/help_topics/documentimport.html': {'before': '91eb31851304c0400768dfb9be425083b16d262de3794e69560d6364b00b55cf', 'after': '2740e16302c7031e6d150712d882b35f0b2dbc8e7201675bcf616363209525fd', 'bytes': 39380, 'payload': ''}, 'app/static/help_topics/inventorybuilder.html': {'before': '872de4ff9d7da2d33e3e8804eaa3994bc44d81f1e41b538621dded3903e055c0', 'after': '35a4604a362b134f9c0a65ae19ff03d0c4c7325cad1909c319c7958e06e24360', 'bytes': 31980, 'payload': ''}, 'app/static/index.html': {'before': '855ec1652641dd8e9b488bedfc7bd30c8238b9bb22c087ad080584fe6562aabe', 'after': '7de663ee1be51168f25a12f5a6bc26e07591501b946c9e705c2b72897daf8521', 'bytes': 24839, 'payload': ''}, 'app/static/sw.js': {'before': '54d7a15149721ff21b104aba27202528e93eccf7c212f51b286e4e30b4ae9f8d', 'after': '40853e0dae1976e5b7578e9ce8a39129989fa67f78367d1b7f561b5f2777e69a', 'bytes': 13523, 'payload': ''}, 'docs/user/topics/documentimport.html': {'before': 'fece0a4bb1e16fdb5af5da8fc852fd653c15834686005e60c040fcc3b3ea688d', 'after': 'ddd2a1b1d1c85be69792945848e88c45fefca2bdfdbb874dde26d2d5832538c3', 'bytes': 20022, 'payload': ''}, 'docs/user/topics/inventorybuilder.html': {'before': '79821ad18fdccd8fbf8c801d2944926318d5a6ab4cc3604dc00fc04c4f03b44d', 'after': '7f9de825981b43fb624bee612e6be11b6d394674a4185e5ad94a61c8ed1a8bec', 'bytes': 16155, 'payload': ''}, 'tests/test_inventory_navigation_ui112.js': {'before': None, 'after': '975ffbd712a8b066ea53ba4ca45270c8c776100a2b72fb0ee57a110eb6d10815', 'bytes': 22081, 'payload': ''}}

def apply(destination: Path) -> None:
    manifest_path=destination/'RELEASE_FILES.json'
    raw=manifest_path.read_bytes()
    if hashlib.sha256(raw).hexdigest()!=PARENT_MANIFEST_SHA256:
        raise ValueError('UI112 requires the exact UI111 source manifest. Do not deploy.')
    manifest=json.loads(raw)
    for name,expected in manifest['files'].items():
        relative=PurePosixPath(name)
        if relative.is_absolute() or '..' in relative.parts:
            raise ValueError('Unsafe source manifest path.')
        path=destination.joinpath(*relative.parts)
        if path.is_symlink() or not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=expected:
            raise ValueError('UI112 parent resource mismatch: '+name)
    prepared={}
    for name,record in FILES.items():
        path=destination/name
        if record['before'] is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('UI112 new resource already exists: '+name)
        elif manifest['files'].get(name)!=record['before']:
            raise ValueError('UI112 parent file mismatch: '+name)
        dec=zlib.decompressobj()
        data=dec.decompress(base64.b64decode(record['payload'],validate=True),record['bytes']+1)
        data+=dec.flush()
        if not dec.eof or dec.unused_data or dec.unconsumed_tail or len(data)!=record['bytes'] or hashlib.sha256(data).hexdigest()!=record['after']:
            raise ValueError('UI112 payload integrity failure: '+name)
        prepared[name]=data
    for name,data in prepared.items():
        path=destination/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
        manifest['files'][name]=FILES[name]['after']
    manifest['variant']=TARGET_VARIANT
    manifest_path.write_text(json.dumps(manifest,indent=2)+'\n')
    for name,expected in manifest['files'].items():
        if hashlib.sha256((destination/name).read_bytes()).hexdigest()!=expected:
            raise ValueError('Derived UI112 integrity failure: '+name)

if __name__=='__main__':
    apply(Path(sys.argv[1]))
    print('Applied Workspace UI112: clearer inventory review navigation and source-column mapping; rows, signed review and retry requests retained.')
